// Success path only -- the failure branch notifies then throws.
const res = $('PingSupabase').first().json;
return [{ json: { ok: true, statusCode: res.statusCode, checkedAt: new Date().toISOString() } }];

// Notify first, THEN throw. Throwing is what makes n8n record a failed
// execution (the pull signal); the WhatsApp is the push signal. Both, in that
// order, so a Twilio failure cannot swallow the execution-level alarm.
const ping = $('PingSupabase').first().json;
const notify = $input.first().json;
const email = $('AssertEmailSent').first().json;
const notified = notify.statusCode >= 200 && notify.statusCode < 300;
throw new Error(
  'SUPABASE KEEPALIVE FAILED -- platform DB unreachable. statusCode=' + ping.statusCode +
  '. Email alert ' + (email.emailOk ? 'SENT (' + email.emailId + ')' : 'NOT SENT') +
  '. Operator WhatsApp alert ' + (notified ? 'SENT' : 'ALSO FAILED (' + notify.statusCode + ')') +
  '. Most likely the free-tier project has auto-paused (7 days idle) or the ' +
  'service_role key was rotated. Check the Supabase dashboard first.');

// The email node has onError:continueRegularOutput, so a rejected send arrives
// here looking exactly like a successful one -- an item, no exception, status
// 'success'. That is how a mis-typed credential header sent zero alerts while
// three executions reported success (engineering-lessons.md).
const res = $input.first().json;
const code = res && res.statusCode;
const ok = code >= 200 && code < 300;
const err = (res && res.error) ? (res.error.message || JSON.stringify(res.error))
                               : ((res && res.body && res.body.message) || 'no response');
if (!ok) {
  throw new Error('KEEPALIVE ALERT EMAIL NOT SENT (' + (code || 'no status') + '): ' + err
    + ' -- Supabase is unreachable AND nobody has been told by email.');
}
return [{ json: { ...res, emailOk: true, emailId: (res.body || {}).id || null } }];
